use verus::prelude::*;

verus! {

    /// Returns the index of the first occurrence of the minimum element in a non‐empty vector.
    ///
    /// # Safety / Specification
    /// * `a.len() > 0`
    /// * The returned index is in bounds.
    /// * `a[result]` is ≤ every element in `a`.
    /// * For any `i < result`, `a[i] > a[result]` (first occurrence of the minimum).
    fn getmini(a: &Vec<i32>) -> usize
        requires
            a.len() > 0,
        ensures
            // result is a valid index
            result < a.len(),
            // a[result] is the minimum value in the entire array
            forall(|i: usize| i < a.len() ==> a[result] <= a[i]),
            // for any index strictly before result, the value there is strictly greater
            forall(|i: usize| i < result ==> a[i] > a[result]),
    {
        // We scan from left to right, keeping track of the
        // index `imin` of the smallest value seen so far.
        let mut imin: usize = 0;
        // `j` is the next position to inspect.
        let mut j: usize = 1;

        // Loop invariant maintains that:
        //  1) 0 ≤ j ≤ a.len()
        //  2) imin < j
        //  3) a[imin] is the minimum of a[0..j)
        //  4) For all k < imin, a[k] > a[imin]  (first‐occurrence property on the prefix)
        while j < a.len()
            invariant
                j <= a.len(),
                imin < j,
                forall(|k: usize| k < j ==> a[imin] <= a[k]),
                forall(|k: usize| k < imin ==> a[k] > a[imin]),
            decreases
                a.len() - j,
        {
            if a[j] < a[imin] {
                // Found a strictly smaller element at j,
                // update imin to the first occurrence of this new minimum.
                imin = j;
            } else {
                // Otherwise, we know a[j] ≥ a[imin], which will help
                // preserve the "a[imin] ≤ a[k] for all k < new j" invariant.
                assert(a[imin] <= a[j]);
            }
            j += 1;
        }

        // At termination, j == a.len(), so imin is the first index
        // of the global minimum in a[0..a.len()).
        imin
    }

}